// Generated by AI (UnitTest MCP)

export type DesignStatus = "proposed" | "accepted" | "rejected";
export type DesignPromotionStatus = "not_required" | "pending" | "materialized";

export interface DesignItem {
  id: string;
  adr_path: string;
  title: string;
  summary: string;
  status: DesignStatus;
  proposed_by?: string | null;
  decided_by?: string | null;
  reason?: string | null;
  created_at: number;
  updated_at: number;
  promotion_status: DesignPromotionStatus;
  materialization_revision: number;
}

export interface DesignTask {
  id: string;
  goal_id: string;
  title: string;
  acceptance: string;
  status: string;
}

export interface DesignGoal {
  id: string;
  title: string;
  kind: string;
}

export interface DesignPromotion {
  item: DesignItem;
  mode: DesignMaterializationMode;
  revision: number;
  rationale?: string | null;
  goals: DesignGoal[];
  tasks: DesignTask[];
  constraints: DesignGoal[];
}

export type DesignMaterializationMode = "create" | "link" | "no_work";

export interface DesignTaskDraft {
  goal_id: string;
  title: string;
  acceptance: string;
}

export interface DesignConstraintDraft {
  kind: "constraint" | "invariant";
  title: string;
  statement: string;
}

export interface DesignMaterializationPlan {
  mode: DesignMaterializationMode;
  tasks?: DesignTaskDraft[];
  task_ids?: string[];
  constraints?: DesignConstraintDraft[];
  rationale?: string | null;
}

export interface DesignMaterializationRecord {
  design_id: string;
  revision: number;
  plan: DesignMaterializationPlan;
  actor: string;
  created_at: number;
}

export interface DesignMetadata {
  adr_path: string;
  title: string;
  summary: string;
  status: DesignStatus;
  proposed_by?: string;
}

export interface DesignBoardRow {
  id: string;
  label: string;
  description: string;
  tooltip: string;
  contextValue: string;
  item: DesignItem;
  promotion?: DesignPromotion;
}

const DESIGN_STATUS_ORDER: Record<string, number> = {
  proposed: 0,
  pending: 1,
  materialized: 2,
  historical: 3,
  rejected: 4,
};

/** Cap on the summary handed to planning, so a long ADR cannot flood the prompt. */
const SUMMARY_MAX_CHARS = 2000;

function adrSection(content: string, heading: string): string {
  const start = new RegExp(`^##\\s+${heading}\\b[^\\n]*$`, "im").exec(content);
  if (!start) {
    return "";
  }
  const rest = content.slice(start.index + start[0].length);
  const next = /^##\s/m.exec(rest);
  return (next ? rest.slice(0, next.index) : rest).trim();
}

/**
 * The decision text design planning needs: `## Decision` says what to build and
 * `## Context` says why. Without it the planner sees only the ADR title and
 * invents generic filler work, which is how an accepted design turns into
 * duplicate or orphan tasks (ADR-0028).
 */
export function extractAdrSummary(content: string): string {
  const body = [adrSection(content, "Decision"), adrSection(content, "Context")]
    .filter(Boolean)
    .join("\n\n")
    .trim();
  if (body.length <= SUMMARY_MAX_CHARS) {
    return body;
  }
  const clipped = body.slice(0, SUMMARY_MAX_CHARS);
  const boundary = clipped.lastIndexOf("\n");
  return (boundary > 0 ? clipped.slice(0, boundary) : clipped).trimEnd();
}

/**
 * The `- Status:` line: emphasis stripped, whitespace collapsed, lowercased.
 *
 * A value that wraps onto an indented continuation line is read whole.
 * ADR-0032 puts its successor on the next line, and a pattern that stopped at
 * the newline read a bare "superseded by" — losing the reference that was one
 * line further down. Continuation lines are indented and are not the next `- `
 * bullet or a heading.
 *
 * This mirrors the rule in `scripts/adr-files.mjs`, which says in its own header
 * that a second parser would drift from it the moment either learned a new
 * status. This is that second parser; it drifted, and these are the four things
 * it had not learned — the continuation line, `Superseded`, the generated index
 * (see {@link isAdrFile}), and that a skip is a decision the board cannot show.
 */
const ADR_STATUS_PATTERN =
  /^[ \t]*-?[ \t]*(?:\*\*)?Status:(?:\*\*)?[ \t]*([^\r\n]*(?:\r?\n[ \t]+(?![-*#][ \t])[^\r\n]+)*)/im;

export function rawAdrStatus(content: string): string | undefined {
  const status = content
    .match(ADR_STATUS_PATTERN)?.[1]
    ?.replace(/\*/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
  return status || undefined;
}

/**
 * Whether a path names an ADR, by the same rule `scripts/adr-files.mjs` uses.
 *
 * `docs/adr/README.md` is the index generated by `scripts/adr-index.mjs`, not a
 * decision. Scanning it produced a "no readable title or Status line" skip on
 * every load, which inflated the skip count and made a working warning read
 * like a defect.
 */
export function isAdrFile(pathOrName: string): boolean {
  const name = pathOrName.replace(/\\/g, "/").split("/").pop() ?? "";
  return /^\d{4}-.*\.md$/.test(name);
}

/**
 * `Accepted (implemented)` is still accepted: a parenthetical is commentary on
 * a decision, not a different lifecycle state. Requiring an exact match dropped
 * ADR-0015 and ADR-0017 from the ledger entirely — the board cannot show a
 * design it never registered, and nothing reported the loss.
 *
 * `Superseded by <ref>` is **accepted** too. ADR-0050 was explicit that
 * superseding keeps the row accepted and adds a link to its successor, so a
 * live design is one with no `superseded_by`. Returning undefined here dropped
 * ADR-0018 and ADR-0032, and registering them as accepted is what makes a later
 * supersession possible at all — a row that is not in the ledger cannot be
 * superseded in it.
 *
 * The successor link is deliberately not derived from the file. Supersession is
 * an attributed human act, guarded on an accepted row with a recorded decider
 * and an already-registered replacement; a scan that asserted it would repeat
 * the mistake ADR-0042 refuses when it declines to auto-retire a design whose
 * file is merely absent from this checkout.
 */
export function normalizeAdrStatus(raw: string | undefined): DesignStatus | undefined {
  const head = raw?.replace(/\s*\(.*$/, "").trim();
  if (!head) {
    return undefined;
  }
  if (/^superseded\b/.test(head)) {
    return "accepted";
  }
  return isDesignStatus(head) ? head : undefined;
}

export function parseAdrMetadata(
  adrPath: string,
  content: string,
  proposedBy?: string
): DesignMetadata | null {
  const normalizedPath = adrPath.replace(/\\/g, "/");
  const title = content.match(/^#\s+(.+?)\s*$/m)?.[1]?.trim();
  const status = normalizeAdrStatus(rawAdrStatus(content));
  if (!title || !status) {
    return null;
  }
  return {
    adr_path: normalizedPath,
    title,
    summary: extractAdrSummary(content),
    status,
    ...(proposedBy ? { proposed_by: proposedBy } : {}),
  };
}

export function designBoardRows(
  designs: DesignItem[],
  promotions: ReadonlyMap<string, DesignPromotion> = new Map()
): DesignBoardRow[] {
  return [...designs]
    .map((item) => toRow(item, promotions.get(item.id)))
    .sort((left, right) => {
      const statusDelta =
        (DESIGN_STATUS_ORDER[left.contextValue] ?? Number.MAX_SAFE_INTEGER) -
        (DESIGN_STATUS_ORDER[right.contextValue] ?? Number.MAX_SAFE_INTEGER);
      return (
        statusDelta ||
        left.item.created_at - right.item.created_at ||
        left.id.localeCompare(right.id)
      );
    });
}

export function designContext(item: DesignItem): string {
  if (item.status === "proposed") {
    return "proposed";
  }
  if (item.status === "rejected") {
    return "rejected";
  }
  if (item.promotion_status === "pending") {
    return "pending";
  }
  if (item.promotion_status === "materialized") {
    return "materialized";
  }
  return "historical";
}

export function replaceAdrStatus(content: string, status: DesignStatus): string | null {
  const pattern = /^(\s*-?\s*(?:\*\*)?Status:(?:\*\*)?\s*)([^\r\n]+)/im;
  if (!pattern.test(content)) {
    return null;
  }
  const label = status[0].toUpperCase() + status.slice(1);
  return content.replace(pattern, (_match, prefix: string) => `${prefix}${label}`);
}

/** Which checkout should receive an accepted design's ADR status write. */
export type AdrTargetChoice =
  { kind: "none" } | { kind: "one"; target: string } | { kind: "ambiguous"; candidates: string[] };

/**
 * Decide where an ADR status write goes, given every attached workspace folder
 * that actually contains the path.
 *
 * Deliberately refuses to pick for you when several match. An ADR's declared
 * status is evidence of a human decision, and under ADR-0038 a fleet routinely
 * has several worktrees of one repository open on different branches — so
 * "the first folder containing this path" is close to arbitrary, and getting it
 * wrong records that decision on a branch nobody made it on.
 */
export function chooseAdrTarget(candidates: string[]): AdrTargetChoice {
  if (candidates.length === 0) {
    return { kind: "none" };
  }
  if (candidates.length === 1) {
    return { kind: "one", target: candidates[0] };
  }
  return { kind: "ambiguous", candidates: [...candidates] };
}

export function formatMaterializationPlan(
  plan: DesignMaterializationPlan,
  linkedTasks: DesignTask[] = []
): string {
  const lines = [`Mode: ${plan.mode.replace("_", " ")}`];
  for (const task of plan.tasks ?? []) {
    lines.push(`Create: ${task.title} (${task.goal_id})`, `Done when: ${task.acceptance}`);
  }
  for (const taskId of plan.task_ids ?? []) {
    const task = linkedTasks.find((candidate) => candidate.id === taskId);
    lines.push(`Link: ${task ? `${task.title} (${task.id})` : taskId}`);
  }
  if (plan.rationale) {
    lines.push(`Rationale: ${plan.rationale}`);
  }
  return lines.join("\n");
}

export function formatDesignPromotion(
  promotion: DesignPromotion,
  history: DesignMaterializationRecord[] = []
): string {
  const objective =
    promotion.goals.length === 0
      ? "none"
      : promotion.goals.map((goal) => `${goal.title} (${goal.id})`).join(", ");
  const lines = [
    `# Design materialization: ${promotion.item.title}`,
    "",
    `- **ADR:** ${promotion.item.adr_path}`,
    `- **Mode:** ${promotion.mode}`,
    `- **Revision:** ${promotion.revision}`,
    `- **Objectives:** ${objective}`,
    `- **Tasks:** ${promotion.tasks.length}`,
    `- **Constraints:** ${promotion.constraints.length}`,
  ];
  if (promotion.rationale) {
    lines.push(`- **Rationale:** ${promotion.rationale}`);
  }
  if (promotion.tasks.length) {
    lines.push("", "## Tasks");
    for (const task of promotion.tasks) {
      lines.push(`- ${task.title} — ${task.status} (${task.id})`);
    }
  }
  if (promotion.constraints.length) {
    lines.push("", "## Constraints");
    for (const goal of promotion.constraints) {
      lines.push(`- ${goal.title} — ${goal.kind} (${goal.id})`);
    }
  }
  if (history.length) {
    lines.push("", "## Revision history");
    for (const record of history) {
      lines.push(
        `- r${record.revision} — ${record.plan.mode} by ${record.actor}: ${record.plan.rationale ?? "initial materialization"}`
      );
    }
  }
  return lines.join("\n");
}

function toRow(item: DesignItem, promotion?: DesignPromotion): DesignBoardRow {
  const contextValue = designContext(item);
  const details: string[] = [item.adr_path];
  if (item.summary) {
    details.push(item.summary);
  }
  if (item.proposed_by) {
    details.push(`proposed by: ${item.proposed_by}`);
  }
  if (item.decided_by) {
    details.push(`decided by: ${item.decided_by}`);
  }
  if (item.reason) {
    details.push(`reason: ${item.reason}`);
  }
  if (promotion) {
    for (const goal of promotion.goals) {
      details.push(`objective: ${goal.title} (${goal.id})`);
    }
    details.push(`mode: ${promotion.mode}; revision: ${promotion.revision}`);
    details.push(`tasks: ${promotion.tasks.length}; constraints: ${promotion.constraints.length}`);
  }
  return {
    id: item.id,
    label: item.title,
    description: describe(item, promotion),
    tooltip: details.join("\n"),
    contextValue,
    item,
    ...(promotion ? { promotion } : {}),
  };
}

function describe(item: DesignItem, promotion?: DesignPromotion): string {
  switch (designContext(item)) {
    case "proposed":
      return "proposed · review required";
    case "pending":
      return "accepted · promotion pending";
    case "materialized":
      return promotion?.mode === "no_work"
        ? `materialized · no new work · r${promotion.revision}`
        : `materialized · ${promotion?.tasks.length ?? 0} tasks · r${promotion?.revision ?? 0}`;
    case "rejected":
      return "rejected";
    default:
      return "accepted · historical";
  }
}

function isDesignStatus(value: string): value is DesignStatus {
  return value === "proposed" || value === "accepted" || value === "rejected";
}
